import{_ as r,o as t,c as a,ah as n}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Remunerations and commissions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/remunerations.md","filePath":"src/en/guide/coordinateur/remunerations.md"}'),s={name:"en/guide/coordinateur/remunerations.md"};function o(i,e,l,c,h,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="remunerations-and-commissions" tabindex="-1">Remunerations and commissions <a class="header-anchor" href="#remunerations-and-commissions" aria-label="Permalink to &quot;Remunerations and commissions&quot;">​</a></h1><p>Sums due to trainers, coaches, jury members, business referrers and marketing partners are prepared in <strong>Finance</strong>. Kura calculates or records, <strong>you validate</strong>, then you <strong>record the payment made outside Kura</strong>: Kura executes no transfer.</p><h2 id="trainers-coaches-and-jury" tabindex="-1">Trainers, coaches and jury <a class="header-anchor" href="#trainers-coaches-and-jury" aria-label="Permalink to &quot;Trainers, coaches and jury&quot;">​</a></h2><p><strong>Finance → Remunerations</strong> lists each payee&#39;s lines, by cohort and by kind: teaching hours, project lump sum, coaching, jury token.</p><h3 id="the-pay-grid" tabindex="-1">The pay grid <a class="header-anchor" href="#the-pay-grid" aria-label="Permalink to &quot;The pay grid&quot;">​</a></h3><p>From the page, the <strong>pay grid</strong> gives the rates in force: hourly rate by profitability zone, project lump sum per cohort, coaching lump sum per learner at the start, jury token per member and per defence date. <strong>Schedule a rate</strong> makes it take effect on a date. A cohort keeps the rates in force <strong>at its start</strong>.</p><h3 id="calculating" tabindex="-1">Calculating <a class="header-anchor" href="#calculating" aria-label="Permalink to &quot;Calculating&quot;">​</a></h3><p>At the end of a cohort, Kura calculates:</p><ul><li><strong>teaching hours</strong>: the program&#39;s hours × the <strong>zone&#39;s rate at the start</strong>;</li><li>the <strong>project lump sum</strong>;</li><li><strong>coaching</strong>: headcount at the start × lump sum per learner.</li></ul><p>If several trainers (or several coaches) share the cohort, the sum is <strong>split equally</strong>. The headcount and zone used are those of the <strong>start</strong>, even if a learner drops out afterwards.</p><p>If a rate was missing at the close, the cohort appears under <strong>Completed cohorts to calculate</strong> with the missing rates: complete the grid, then <strong>Calculate</strong>.</p><p><strong>Jury tokens</strong> are due to each recorded member (see <a href="./resultats.html#the-jury-members">Results and certification</a>) once the defence date has passed.</p><h3 id="adjusting-validating-paying" tabindex="-1">Adjusting, validating, paying <a class="header-anchor" href="#adjusting-validating-paying" aria-label="Permalink to &quot;Adjusting, validating, paying&quot;">​</a></h3><ol><li><strong>Adjust</strong> a line if needed: the calculated amount stays visible, the adjustment is logged.</li><li>Select lines and <strong>validate</strong> them.</li><li>When the payment is made, <strong>record it</strong>: the validated lines are settled.</li></ol><p>Each payee follows their lines in <strong>My remuneration</strong>.</p><h2 id="business-referrer-commissions" tabindex="-1">Business referrer commissions <a class="header-anchor" href="#business-referrer-commissions" aria-label="Permalink to &quot;Business referrer commissions&quot;">​</a></h2><p><strong>Finance → Commissions</strong> tracks business referrers. The referrer earns <strong>5% of each payment</strong> of the enrolment they brought, funder&#39;s share included: nothing on a mere candidature, nothing on an instalment never paid. A refund takes the commission back through a negative line.</p><ol><li>Search for the referrer, a code or a learner, and filter by status (<strong>Calculated</strong>, <strong>Validated</strong>, <strong>Paid</strong>).</li><li><strong>Validate the selection</strong> for calculated lines.</li><li><strong>Record the payout</strong> to a referrer, with the date: the validated lines are settled.</li></ol><p>The referrer sees their code, their referred enrolments and their commissions in <strong>My commissions</strong>.</p><h2 id="marketing-partners" tabindex="-1">Marketing partners <a class="header-anchor" href="#marketing-partners" aria-label="Permalink to &quot;Marketing partners&quot;">​</a></h2><p><strong>Finance → Marketing partners</strong> tracks partners whose remuneration is made <strong>on invoice submission</strong>, never by number of enrolments.</p><ul><li>The <strong>Partnerships Officer</strong> records each partner&#39;s <strong>contracts</strong> and <strong>campaign fees</strong> (type, title, amount, period).</li><li>The partner <strong>submits their invoices</strong> (number, amount, date, PDF of 5 MB at most), within the amount of each contract.</li><li>You <strong>validate</strong> the invoice, or <strong>reject</strong> it with a reason: the reason is passed to the partner, who can submit a corrected invoice, and the amount and number are freed.</li><li>After the payment made outside Kura, <strong>Record the payment</strong> with its date.</li></ul><p>The partner&#39;s tracking code (<code>MK-XXXXXX</code>) is given when the role is assigned, for information.</p>',23)])])}const m=r(s,[["render",o]]);export{g as __pageData,m as default};
